Definition MQ {X} (Q : postM X) : postT (exc (X * St)) := EQ (fun p RNG A mo => Q (fst p) RNG A (snd p) mo).

Definition TSM {X} (P : preT) (m : M St X) (Q : postM X) : Prop :=
  forall RNG A s mo, P RNG A s mo -> TS RNG A (m s) mo (MQ Q).

